import pandas as pd
import numpy as np

# Load data
transport_data = pd.read_csv('chunks_csv/moran_local_2021_transport.csv')
adjacency_list = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute neighborhood transport energy use averages
neighborhood_averages = {}
for index, row in adjacency_list.iterrows():
    borough = row['borough']
    neighbors = adjacency_list.loc[adjacency_list['neighbor'] == borough, 'borough'].tolist()
    if len(neighbors) > 0:
        neighborhood_averages[borough] = transport_data.loc[transport_data['borough'].isin(neighbors), 'Transport_value'].mean()

# Identify hot and cold spots
hot_spots = []
cold_spots = []
for index, row in transport_data.iterrows():
    borough = row['borough']
    if borough in neighborhood_averages:
        neighbor_avg = neighborhood_averages[borough]
        if row['Transport_value'] > 4000 and neighbor_avg > 4000:
            hot_spots.append((borough, row['Transport_value'], neighbor_avg))
        elif row['Transport_value'] < 2000 and neighbor_avg < 2000:
            cold_spots.append((borough, row['Transport_value'], neighbor_avg))

# Compute statistical significance
def permutation_test(data, value):
    test_statistic = np.mean(data)
    permutations = 500
    p_value = 0
    for _ in range(permutations):
        data_perm = np.random.permutation(data)
        p_value += np.mean(data_perm) >= value
    p_value /= permutations
    return test_statistic, p_value

for borough, transport_value, neighbor_avg in hot_spots + cold_spots:
    if borough in transport_data['borough'].values:
        data_points_used = len(transport_data[transport_data['borough'] != 'borough'])
        test_statistic, p_value = permutation_test(transport_data['Transport_value'], transport_value)
        if p_value < 0.05:
            print(f"FINAL ANSWER: {borough} (HH, test statistic = {test_statistic}, significance measure = {p_value})")
